// 本地图片资源模块声明（Expo web / metro 打包的静态图片）
declare module '*.png' {
  const value: number
  export default value
}
declare module '*.jpg' {
  const value: number
  export default value
}
declare module '*.jpeg' {
  const value: number
  export default value
}
declare module '*.svg' {
  const value: number
  export default value
}
declare module '*.webp' {
  const value: number
  export default value
}
